#include <string>

// Реализуйте типы и операции из условия.
int solve(int a,int b){
    (void)a; (void)b;
    return 0;
}

exercise.referenceSolution:
#include <iostream>
#include <memory>
#include <vector>
#include <utility>
#include <string>

int solve(int a,int b){(void)b; const int diagnosis[4]={2,0,0,1}; return diagnosis[a];}

