additionalExercises.referenceSolution:
#include <iostream>
#include <memory>
#include <vector>
#include <utility>
#include <string>

int solve(int a, int b) { auto owner = std::make_unique<int>(a); int saved = *owner; owner.reset(); return saved + b; }
